const fs = require('fs');
const path = require('path');
const { randomUUID } = require('crypto');

const state = items[0].json;

if (!state.payload || !state.plan) {
  throw new Error('Invalid envelope: payload or plan missing');
}

state.payload.context = state.payload.context || {};
state.payload.context.human = state.payload.context.human || {};

const baseDir = path.resolve(process.cwd(), 'push_runs');
if (!fs.existsSync(baseDir)) {
  fs.mkdirSync(baseDir, { recursive: true });
}

const runId = state.payload.context.run_id || `run_${Date.now()}_${randomUUID()}`;
state.payload.context.run_id = runId;

const record = {
  run_id: runId,
  saved_at: new Date().toISOString(),
  envelope: state
};

const filePath = path.join(baseDir, `${runId}.json`);
fs.writeFileSync(filePath, JSON.stringify(record, null, 2));

state.payload.context.human.storage = {
  run_id: runId,
  file_path: filePath
};

return [{ json: state }];

const state = items[0].json;

const runId = state.payload?.context?.run_id || 'unknown';
const stepsCount = Array.isArray(state.plan?.steps) ? state.plan.steps.length : 0;
const summary = state.payload?.context?.validation?.plan_schema?.valid
  ? `Plan ready (${stepsCount} steps).`
  : `Plan needs review (${stepsCount} steps).`;

state.payload.context.human = state.payload.context.human || {};
state.payload.context.human.approval_request = {
  run_id: runId,
  summary,
  instructions: `Approve by sending: "approve ${runId}" or reject with: "reject ${runId}".`
};

state.payload.context.human.slack = {
  message: `SmartOffice approval needed\nRun: ${runId}\n${summary}\nApprove: approve ${runId}\nReject: reject ${runId}`
};

return [{ json: state }];

const fs = require('fs');
const path = require('path');

const payload = items[0].json || {};
const text = payload.text || payload.event?.text || payload.message?.text || '';

const match = text.match(/(approve|reject)\s+(run_[\w-]+)/i);
if (!match) {
  throw new Error('No approval command found (expected "approve <run_id>")');
}

const action = match[1].toLowerCase();
const runId = match[2];

const filePath = path.resolve(process.cwd(), 'push_runs', `${runId}.json`);
if (!fs.existsSync(filePath)) {
  throw new Error(`Run not found: ${runId}`);
}

const record = JSON.parse(fs.readFileSync(filePath, 'utf8'));
const state = record.envelope;

if (!state || !state.payload) {
  throw new Error('Persisted envelope missing');
}

if (action !== 'approve') {
  const rejectBy = payload.user || payload.event?.user || 'slack';
  throw new Error(`Run ${runId} rejected by ${rejectBy}`);
}

state.payload.context = state.payload.context || {};
state.payload.context.human = state.payload.context.human || {};
state.payload.context.human.approved_at = new Date().toISOString();
state.payload.context.human.approved_action = action;
state.payload.context.human.approved_by = payload.user || payload.event?.user || 'slack';

const existingAuthorization = (state.authorization && typeof state.authorization === 'object')
  ? state.authorization
  : {};

state.authorization = {
  ...existingAuthorization,
  mode: 'human_approved'
};

return [{ json: state }];

